public boolean[] sieveOfEratosthenes(int n) {
    boolean[] isComposite = new boolean[n + 1];
    for (int p = 2; (long) p * p <= n; p++) {
        if (!isComposite[p]) {
            for (int multiple = p * p; multiple <= n; multiple += p) {
                isComposite[multiple] = true;
            }
        }
    }
    boolean[] isPrime = new boolean[n + 1];
    for (int i = 2; i <= n; i++) isPrime[i] = !isComposite[i];
    return isPrime;
}

public long fastPow(long base, long exp, long mod) {
    long result = 1;
    base %= mod;
    while (exp > 0) {
        if ((exp & 1) == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

public int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}
public long lcm(long a, long b) {
    return (a / gcd((int) a, (int) b)) * b;
}

public boolean canPartition(int[] nums, int target) {
    int n = nums.length, half = n / 2;
    List<Integer> leftSums = enumerateSums(nums, 0, half);
    List<Integer> rightSums = enumerateSums(nums, half, n);
    Collections.sort(rightSums);
    for (int ls : leftSums) {
        int need = target - ls;
        if (Collections.binarySearch(rightSums, need) >= 0) return true;
    }
    return false;
}
private List<Integer> enumerateSums(int[] nums, int start, int end) {
    List<Integer> sums = new ArrayList<>();
    int len = end - start;
    for (int mask = 0; mask < (1 << len); mask++) {
        int sum = 0;
        for (int i = 0; i < len; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[start + i];
        }
        sums.add(sum);
    }
    return sums;
}
